head.script:
/* =========================================================================
 * WAEA-860 검증용 _fix 샘플
 * 핫픽스: 2026_0518_hotfix_WAEA_860.js (기준 REL_6_0_0_1438B_20260120_113942)
 *
 * 목적: submission mode=synchronous 일 때도 withCredentials 설정값이
 *       실제 XMLHttpRequest.send 직전에 정상 반영되는지 확인.
 *
 * 확인 방법: 각 버튼을 누르고 콘솔의 "[XHR send] withCredentials = ..." 로그 확인.
 *   - 압축 엔진 코드(r.send(b))를 직접 안 봐도 send 직전 값이 그대로 찍힘.
 * ========================================================================= */

// --- (1) XHR 가로채기: send 직전 withCredentials 값을 콘솔에 출력 ---
(function () {
    if (XMLHttpRequest.prototype.__waea860Patched) { return; }
    XMLHttpRequest.prototype.__waea860Patched = true;

    var _open = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url, async) {
        this.__waea860_url = url;
        this.__waea860_async = (async !== false); // 미지정 시 기본 true
        return _open.apply(this, arguments);
    };

    var _send = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (body) {
        console.log(
            "[XHR send] withCredentials =", this.withCredentials,
            "| mode =", (this.__waea860_async ? "asynchronous" : "synchronous"),
            "| url =", this.__waea860_url
        );
        return _send.apply(this, arguments);
    };
})();

// --- (2) 공통 submission 실행 함수 ---
scwin.runCase = function (caseId, opt) {
    // 같은 id 재실행 시 중복 방지를 위해 기존 submission 제거
    try { $p.removeSubmission(caseId); } catch (e) {}

    var tmpOpt = {
        id: caseId,
        target: "data:json,dataList1",
        action: "gridView_submission_create_WAEA-860_(WSQ-6322).json",
        mediatype: "application/json",
        submitDoneHandler: "scwin.submitDoneHandler"
    };
    // 케이스별 옵션 병합 (mode / withCredentials)
    for (var k in opt) { tmpOpt[k] = opt[k]; }

    console.log("==== [" + caseId + "] 실행 / 설정값:",
        "mode =", tmpOpt.mode,
        ", withCredentials =", (tmpOpt.hasOwnProperty("withCredentials") ? tmpOpt.withCredentials : "(미지정)"));

    $p.createSubmission(tmpOpt);
    $p.executeSubmission(caseId);
};

scwin.submitDoneHandler = function (e) {
    // 응답 수신 확인용
    // console.log("submitDone", e);
};

// --- (3) 검증 케이스 ---
// 케이스 1) 동기 + withCredentials true  → 기대: 핫픽스 후 true (핫픽스 전 false=버그)
scwin.btnSyncTrue_onclick = function () {
    scwin.runCase("caseSyncTrue", { mode: "synchronous", withCredentials: "true" });
};
// 케이스 2) 비동기 + withCredentials true → 기대: true (하위호환 유지)
scwin.btnAsyncTrue_onclick = function () {
    scwin.runCase("caseAsyncTrue", { mode: "asynchronous", withCredentials: "true" });
};
// 케이스 3) 동기 + withCredentials false → 기대: false (기본값 유지)
scwin.btnSyncFalse_onclick = function () {
    scwin.runCase("caseSyncFalse", { mode: "synchronous", withCredentials: "false" });
};
// 케이스 4) 동기 + withCredentials 미지정 → 기대: false (기본값 유지)
scwin.btnSyncNone_onclick = function () {
    scwin.runCase("caseSyncNone", { mode: "synchronous" });
};
// 케이스 전체 순차 실행
scwin.btnRunAll_onclick = function () {
    scwin.btnSyncTrue_onclick();
    scwin.btnAsyncTrue_onclick();
    scwin.btnSyncFalse_onclick();
    scwin.btnSyncNone_onclick();
};

scwin.onpageload = function () {
    console.log("WAEA-860 _fix 로드 완료. 버튼을 눌러 case별 withCredentials 값을 확인하세요.");
};

scwin.onpageunload = function () {};
